import { call, put, takeEvery, takeLatest } from "redux-saga/effects";

// Login Redux States
import {
    CREATE_USERS_DATA,
    SET_USERS_DATA,
    SET_USER_RELATION_DATA,
    USER_RELATION_DATA,
    USERS_DATA,
    CREATE_USER_RELATION_DATA,
    UPDATE_USER_RELATION_DATA
} from "./actionTypes";
import config from "config/config";
import axios from "axios"
import * as url from "../../helpers/url_helper"
import Swal from "sweetalert2";
import toastr from "toastr";
import "toastr/build/toastr.min.css";
import CryptoJS from "crypto-js";
const key = CryptoJS.enc.Utf8.parse(process.env.REACT_APP_KEY); // 32-byte key
const iv = CryptoJS.enc.Utf8.parse(process.env.REACT_APP_IV);

const decryptData = (encryptedText) => {
    try {
        if (!encryptedText) throw new Error("No encrypted text provided");

        // console.log("🔐 Encrypted Data Received (Frontend):", encryptedText);

        let bytes = CryptoJS.AES.decrypt(encryptedText, key, {
            iv: iv,
            mode: CryptoJS.mode.CBC,
            padding: CryptoJS.pad.Pkcs7,
        });

        let decryptedText = bytes.toString(CryptoJS.enc.Utf8);
        // console.log("✅ Decrypted Data:", decryptedText);

        if (!decryptedText) throw new Error("Decryption failed (empty result)");

        // console.log("✅ Decrypted Data:", decryptedText);

        return JSON.parse(decryptedText);
    } catch (error) {
        console.error("❌ Error decrypting data:", error);
        return null;
    }
};
function* getUsers(request) {
    var axiosConfig = {
        method: 'post',
        url: `${config.API_URL}${url.POST_USERS}`,
        headers: {
            'Content-Type': 'application/json'
        },
        data: request.payload ? request.payload : request
    };
    const result = yield axios(axiosConfig)
    // console.log("Encrypted Response:", result.data);
    const decryptedData =  decryptData(result.data.data);
    if (decryptedData) {
        // console.log("Decrypted Data:", decryptedData);
        yield put({ type: SET_USERS_DATA, data: decryptedData });
      } else {
        console.warn("Decryption returned null");
      }
    // console.log(decryptedData);
    // yield put({ type: SET_USERS_DATA, data: decryptedData })
}

function* userCreate(request) {
    try {

        let positionClass = "toast-top-right";
        toastr.options = {
            positionClass: positionClass,
        };

        var axiosConfig = {
            method: 'post',
            url: `${config.API_URL}${url.POST_CREATE_USER}`,
            headers: {
            },
            data: request.payload
        };
        const result = yield axios(axiosConfig)
        if (result.data.success) {
            const payData = {
                page: 1,
                limit: 40,
                gender: localStorage.getItem('gender') == 'female' ? 'male' : 'female'
            }
            Swal.fire({
                text: `"Record Successfully Added and id is ${result.data.data.id}"`,
                icon: 'success',
                imageAlt: 'success image',
            })
            yield* getUsers(payData)
        }
        else {
            toastr.error(result.data.message)
        }

    } catch (error) {
        console.log('testscatch')
    }
}
function* getUserRelation(request) {
    var axiosConfig = {
        method: 'post',
        url: `${config.API_URL}${url.POST_USERS_RELATION}`,
        headers: {
            'Content-Type': 'application/json'
        },
        data: request.payload ? request.payload : request
    };
    const result = yield axios(axiosConfig)
    const decryptedData =  decryptData(result.data.data);
    if (decryptedData) {
        // console.log("Decrypted Data:", decryptedData);
        // yield put({ type: SET_USERS_DATA, data: decryptedData });
        yield put({ type: SET_USER_RELATION_DATA, data: decryptedData })
      } else {
        console.warn("Decryption returned null");
      }
    // yield put({ type: SET_USER_RELATION_DATA, data: result })
}
function* createUserRelation(request) {
    var axiosConfig = {
        method: 'post',
        url: `${config.API_URL}${url.POST_CREATE_USERS_RELATION}`,
        headers: {
            'Content-Type': 'application/json'
        },
        data: request.payload
    };
    const result = yield axios(axiosConfig)
    if (result.data.success) {
        Swal.fire({
            text: 'your request has been successfully send to them',
            icon: 'success',
            imageAlt: 'success image',
        })
    }
    else {
        Swal.fire({
            text: result.data.message,
            icon: 'success',
            imageAlt: 'success image',
        })
    }
}
function* updateUserRelation(request) {
    var axiosConfig = {
        method: 'post',
        url: `${config.API_URL}${url.POST_UPDATE_USERS_RELATION}`,
        headers: {
            'Content-Type': 'application/json'
        },
        data: request.payload
    };
    const result = yield axios(axiosConfig)
    if (result.data.success) {
        Swal.fire({
            text: 'your request has been updated successfully',
            icon: 'success',
            imageAlt: 'success image',
        })
        const payload = {
            id: localStorage.getItem('id')
        }
        yield* getUserRelation(payload)
    }
    else {
        Swal.fire({
            text: result.data.message,
            icon: 'success',
            imageAlt: 'success image',
        })
    }
}

function* userSaga() {
    yield takeEvery(CREATE_USERS_DATA, userCreate);
    yield takeEvery(USERS_DATA, getUsers);
    yield takeEvery(USER_RELATION_DATA, getUserRelation);
    yield takeEvery(CREATE_USER_RELATION_DATA, createUserRelation);
    yield takeEvery(UPDATE_USER_RELATION_DATA, updateUserRelation);
}

export default userSaga;
