import {
    CREATE_USERS_DATA,
    SET_USERS_DATA,
    SET_USER_RELATION_DATA
} from "./actionTypes";

const INIT_STATE = {
    usersData: [],
    usersRelationData: []
};

const Users = (state = INIT_STATE, action) => {
    switch (action.type) {
        case CREATE_USERS_DATA:
            return {
                ...state,
                usersData: action.payload.data
            };
        case SET_USERS_DATA:
            return {
                ...state,
                // usersData: action.data.data
                usersData: action.data
            };
        case SET_USER_RELATION_DATA:
            return {
                ...state,
                // usersRelationData: action.data.data
                usersRelationData: action.data
            };
        default:
            return state;
    }
}


export default Users;