import {
    CREATE_USERS_DATA,
    USER_RELATION_DATA,
    USERS_DATA,
    CREATE_USER_RELATION_DATA,
    UPDATE_USER_RELATION_DATA
} from "./actionTypes";

// users data
export const getUser = (data) => {
    return {
        type: USERS_DATA,
        payload: data
    }
};
export const getUserRelation = (data) => {
    return {
        type: USER_RELATION_DATA,
        payload: data
    }
};
export const createUserRelation = (data) => {
    return {
        type: CREATE_USER_RELATION_DATA,
        payload: data
    }
};
export const updateUserRelation = (data) => {
    return {
        type: UPDATE_USER_RELATION_DATA,
        payload: data
    }
};
export const createUser = (data) => {
    return {
        type: CREATE_USERS_DATA,
        payload: data
    }
}
